142	static void process_single_touch(lv_indev_t * drv,
143	                                 lv_indev_data_t * data,
144	                                 struct touch_sample_s * sample)
145	{
146	    lv_nuttx_touchscreen_t * touchscreen = drv->driver_data;
147	    uint8_t touch_flags = sample->point[0].flags;
148	
149	    if(touch_flags & (TOUCH_DOWN | TOUCH_MOVE)) {
150	        lv_display_t * disp = lv_indev_get_display(drv);
151	        /* 触摸驱动上报的是面板物理分辨率坐标；display 旋转(90/270)时
152	         * LVGL indev 会再做旋转映射，因此 clamp 必须使用物理分辨率，
153	         * 否则旋转后坐标会被截断。 */
154	        int32_t hor_max = disp->hor_res - 1;
155	        int32_t ver_max = disp->ver_res - 1;
156	
157	        data->point.x = LV_CLAMP(0, sample->point[0].x, hor_max);
158	        data->point.y = LV_CLAMP(0, sample->point[0].y, ver_max);
159	        touchscreen->last_state = LV_INDEV_STATE_PRESSED;
160	
161	        if(touch_flags & TOUCH_DOWN) {
162	            touchscreen->primary_point.id = sample->point[0].id;
163	            touchscreen->primary_point.x = data->point.x;
164	            touchscreen->primary_point.y = data->point.y;
165	        }
166	    }
167	    else if(touch_flags & TOUCH_UP) {
168	        touchscreen->primary_point.id = UINT8_MAX;
169	        touchscreen->last_state = LV_INDEV_STATE_RELEASED;
170	    }
171	}
